/**
 * newFileTemplates — minimal VALID starter files for the "New" context menu.
 *
 * Office templates are real OOXML zips (generated once via python-docx/
 * openpyxl/python-pptx) so Collabora/Word/Excel open them without
 * complaints — an empty 0-byte .docx would be rejected. Text formats are
 * inline strings. Binary content is written through files/v2 write with
 * encoding:"base64".
 */

export interface NewFileTemplate {
  ext: string;
  /** German menu label. */
  label: string;
  content: string;
  encoding: "utf-8" | "base64";
}

const SVG_TEMPLATE = `<?xml version="1.0" encoding="UTF-8"?>
<svg xmlns="http://www.w3.org/2000/svg" width="800" height="600" viewBox="0 0 800 600">
</svg>
`;

const STL_TEMPLATE = `solid neu
endsolid neu
`;

export const NEW_FILE_TEMPLATES: NewFileTemplate[] = [
  { ext: ".txt", label: "Textdatei", content: "", encoding: "utf-8" },
  { ext: ".md", label: "Markdown", content: "# Neu\n", encoding: "utf-8" },
  { ext: ".json", label: "JSON", content: "{}\n", encoding: "utf-8" },
  { ext: ".sh", label: "Shell-Script", content: "#!/bin/bash\n", encoding: "utf-8" },
  { ext: ".csv", label: "CSV-Tabelle", content: "", encoding: "utf-8" },
  { ext: ".docx", label: "Word-Dokument", content: "", encoding: "base64" },
  { ext: ".xlsx", label: "Excel-Tabelle", content: "", encoding: "base64" },
  { ext: ".pptx", label: "Präsentation", content: "", encoding: "base64" },
  { ext: ".svg", label: "Vektorgrafik", content: SVG_TEMPLATE, encoding: "utf-8" },
  { ext: ".png", label: "Pixelgrafik", content: "", encoding: "base64" },
  { ext: ".stl", label: "3D-Modell", content: STL_TEMPLATE, encoding: "utf-8" },
];

export function getTemplate(ext: string): NewFileTemplate | undefined {
  return NEW_FILE_TEMPLATES.find((tpl) => tpl.ext === ext);
}
